css:
.dm1749-container {
  font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #1c2b30;
  background-color: #f6f5f2;
  padding: 18px;
  border-radius: 10px;
  max-width: 1180px;
  margin: 0 auto;
}
.dm1749-header { border-bottom: 3px solid #7a2e3a; padding-bottom: 12px; margin-bottom: 16px; }
.dm1749-header h1 { font-size: 1.6rem; margin: 0 0 4px 0; color: #4a1a24; }
.dm1749-subtitle { font-size: 1rem; margin: 0 0 10px 0; color: #3c5058; }
.dm1749-voice { font-size: 0.94rem; margin: 0; color: #2a3d44; }
.dm1749-badge {
  display: inline-block;
  background-color: #7a2e3a;
  color: #ffffff;
  border-radius: 4px;
  padding: 2px 8px;
  margin-right: 6px;
  font-weight: 600;
}
.dm1749-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 10px;
  margin-bottom: 18px;
}
.dm1749-card {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-left: 4px solid #7a2e3a;
  border-radius: 8px;
  padding: 10px 12px;
}
.dm1749-card-label { font-size: 0.82rem; color: #47585f; margin-bottom: 3px; }
.dm1749-card-value { font-size: 1.32rem; font-weight: 700; color: #4a1a24; }
.dm1749-card-sub { font-size: 0.8rem; color: #55666d; margin-top: 2px; }
.dm1749-score { color: #1f4e79; }
.dm1749-round {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
}
.dm1749-round-title { font-size: 1.16rem; margin: 0 0 8px 0; color: #4a1a24; }
.dm1749-brief {
  font-size: 0.95rem;
  line-height: 1.55;
  color: #26383f;
  background-color: #f4ecee;
  border-left: 3px solid #7a2e3a;
  padding: 10px 12px;
  border-radius: 0 6px 6px 0;
  margin: 0 0 14px 0;
}
.dm1749-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 12px;
}
.dm1749-field { display: flex; flex-direction: column; }
.dm1749-field label { font-size: 0.87rem; font-weight: 600; color: #2a3d44; margin-bottom: 4px; }
.dm1749-container select {
  background-color: #ffffff;
  color: #1c2b30;
  border: 1px solid #7d949c;
  border-radius: 5px;
  padding: 7px 8px;
  font-size: 0.94rem;
  width: 100%;
}
.dm1749-container option { background-color: #ffffff; color: #1c2b30; }
.dm1749-note { font-size: 0.84rem; color: #4d5f66; margin: 12px 0 0 0; font-style: italic; }
.dm1749-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.dm1749-btn-primary {
  background-color: #7a2e3a;
  color: #ffffff;
  border: 1px solid #7a2e3a;
  border-radius: 6px;
  padding: 10px 20px;
  font-size: 0.97rem;
  font-weight: 600;
  cursor: pointer;
}
.dm1749-btn-primary:hover { background-color: #4a1a24; }
.dm1749-container button:disabled { opacity: 0.55; cursor: not-allowed; }
.dm1749-container :focus-visible { outline: 3px solid #1f4e79; outline-offset: 2px; }
.dm1749-history {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-radius: 8px;
  padding: 12px;
}
.dm1749-history table { width: 100%; border-collapse: collapse; font-size: 0.88rem; color: #1c2b30; }
.dm1749-history th {
  text-align: left;
  background-color: #f4ecee;
  color: #1c2b30;
  border-bottom: 2px solid #d6cfc8;
  padding: 6px 8px;
}
.dm1749-history td { border-bottom: 1px solid #e6e0da; padding: 6px 8px; }
.dm1749-cm { font-size: 0.96rem; color: #1c2b30; }
.dm1749-cm-score { font-size: 2.3rem; font-weight: 800; color: #4a1a24; }
.dm1749-cm-max { font-size: 1.05rem; font-weight: 600; color: #55666d; }
.dm1749-cm-verdict { font-size: 1.1rem; font-weight: 700; color: #1f4e79; margin-bottom: 10px; }
.dm1749-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
.dm1749-cm-kpi {
  background-color: #f4ecee;
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 0.88rem;
  color: #26383f;
}
.dm1749-cm-debrief { font-weight: 700; margin: 10px 0 4px 0; color: #4a1a24; }
.dm1749-cm-insights { margin: 0; padding-left: 20px; line-height: 1.55; }
.dm1749-charts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}
.dm1749-chart {
  background-color: #ffffff;
  border: 1px solid #d6cfc8;
  border-radius: 8px;
  padding: 12px;
}
@media (prefers-reduced-motion: reduce) {
  .dm1749-container * { transition: none !important; animation: none !important; }
}

