        _schedule(triage, deploy) {
            var dp = this.DEPLOY[deploy];
            var res = dp[0];
            var travel = dp[1];
            var rule = dp[2];
            var avail = res.map(function(r) { return r[1]; });
            var names = res.map(function(r) { return r[0]; });
            var order = this.ORDER[triage];
            var s = {}, f = {}, who = {};
            var n, j, k, id, mult, skills;
            for (n = 0; n < order.length; n++) {
                id = order.charAt(n);
                skills = this.SKILL[id];
                j = -1;
                for (k = 0; k < names.length; k++) {
                    if (rule === 'skill' && skills.indexOf(names[k]) < 0) { continue; }
                    if (j < 0 || avail[k] < avail[j]) { j = k; }
                }
                mult = (skills.indexOf(names[j]) >= 0) ? 1.0 : this.C.MISMATCH;
                s[id] = avail[j];
                f[id] = s[id] + this.INC[id][0] * mult + travel;
                who[id] = names[j];
                avail[j] = f[id];
            }
            return { s: s, f: f, who: who };
        }

        _outcome(d) {
            var c = this.C;
            var sc = this._schedule(d.triaje1, d.despliegue1);
            var s = sc.s, f = sc.f;
            var alarm = f.A;
            var evac = alarm > c.ALARM_DEADLINE;
            var key = f.B;
            var rc = this.RECUP[d.recup2];
            var em = this.EMPOD[d.empod2];
            var hit = evac ? c.EVAC_HIT : 0.0;
            var self = this;
            var cl = function(x) { return self._clamp(x, 0.05, 0.98); };
            var p = {
                B: cl(rc[0] - 0.01 * Math.max(0.0, key - c.KEY_OK) - hit),
                C: cl(0.97 - 0.015 * Math.max(0.0, f.C - 20.0) - hit),
                D: cl(rc[0] - 0.01 * s.D - hit),
                E: cl(0.92 - 0.015 * s.E - hit),
                R: cl(em[3] - hit)
            };
            var parties = { B: 1, C: 1, D: 12, E: 7, R: c.N_REST };
            var keys = ['B', 'C', 'D', 'E', 'R'];
            var total = 0.0, recovered = 0.0, complaints = 0, lost = 0.0, i, k;
            for (i = 0; i < keys.length; i++) {
                k = keys[i];
                total += parties[k];
                recovered += p[k] * parties[k];
                if (p[k] < 0.5) { complaints += parties[k]; }
                lost += (1 - p[k]) * parties[k] * (k === 'C' ? c.VAL_ORG : c.VAL_PARTY);
            }
            var breach = (d.recup2 === 'aplazar');
            var denied = breach ? (1 + complaints) : 0;
            var spend = rc[1] * c.N_RECUP + em[2] * c.N_REST;
            var evacCost = evac ? c.EVAC_COST : 0.0;
            var nightCost = evacCost + spend + lost;
            var lg = this.LOG[d.registro3];
            var rep = this.APRENDIZ[d.aprendiz3];
            var fx = this.FIX[d.mejora4];
            var qe = lg[0] * rep;
            var m = 0.4 + 0.6 * qe;
            var g = lg[1] * rep;
            var annualInc = 0.0, avoided = 0.0;
            for (i = 0; i < this.CATS.length; i++) {
                var cat = this.CATS[i];
                var r = g + (1 - g) * (cat[0] === fx[0] ? fx[1] * m : 0.0);
                annualInc += cat[1] * (1 - r) * cat[2];
                avoided += cat[1] * r;
            }
            annualInc = annualInc * em[4] * (1 - fx[3]);
            var annual = annualInc + lg[2] + fx[2];
            return { s: s, f: f, who: sc.who, alarm: alarm, evac: evac, key: key, p: p, recovered: recovered / total,
                     complaints: complaints, denied: denied, spend: spend, lost: lost, evacCost: evacCost,
                     nightCost: nightCost, escalated: em[0], restMinutes: em[1], annual: annual, annualInc: annualInc,
                     avoided: avoided, breach: breach, qe: qe };
        }

        _cap(o) {
            return Math.max(this.C.CAP_FLOOR, this.C.CAP_BASE - this.C.CAP_SLOPE * o.denied);
        }

        _roundScore(state, period) {
            var c = this.C;
            var d = this._complete(this._flat(state, period), period);
            var o = this._outcome(d);
            var seg = (o.evac ? 0.0 : 0.5) + 0.5 * this._clamp((c.KEY_BAD - o.key) / (c.KEY_BAD - c.KEY_OK), 0, 1);
            var hue = this._clamp((o.recovered - c.HUE_LO) / (c.HUE_HI - c.HUE_LO), 0, 1);
            var cos = this._clamp((c.COS_HI - o.nightCost) / (c.COS_HI - c.COS_LO), 0, 1);
            var mej = this._clamp((c.ANN_HI - o.annual) / (c.ANN_HI - c.ANN_LO), 0, 1);
            var tw = c.W_SEG + c.W_HUE + c.W_COS + c.W_MEJ;
            var score = 100.0 * (c.W_SEG * seg + c.W_HUE * hue + c.W_COS * cos + c.W_MEJ * mej) / tw;
            score = this._clamp(score, 0, 100);
            if (o.breach) { score = Math.min(score, this._cap(o)); }
            return { score: this._jsround(score), o: o, d: d };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                num += w[p - 1] * this._roundScore(state, p).score;
                den += w[p - 1];
            }
            var total = this._clamp(this._jsround(num / den), 0, 100);
            var o = this._outcome(this._complete(this._flat(state, n), n));
            if (o.breach) { total = Math.min(total, this._jsround(this._cap(o))); }
            return total;
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtSol(n) {
            var v = Math.round(n);
            var s = String(Math.abs(v));
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = ',' + out; }
            }
            var sign = v < 0 ? '-' : '';
            return sign + 'S/ ' + out;
        }

        _pct(n) {
            return String(Math.round(n)) + ' %';
        }

        _min(n) {
            return String(Math.round(n)) + ' ' + this._t('min_unit');
        }

        _alarmTxt(n) {
            return (n < 0) ? this._t('evac_tag') : this._min(n);
        }

        _num(n) {
            return String(Math.round(n));
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(g) {
                var el = document.getElementById(g + period);
                if (el && k[g + period]) { el.value = k[g + period]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var nH = ds.nightHistory || [];
            var rH = ds.recHistory || [];
            var aH = ds.annualHistory || [];
            this._set('nightDisplay', nH.length ? this._fmtSol(nH[nH.length - 1]) : '-');
            this._set('recDisplay', rH.length ? this._pct(rH[rH.length - 1]) : '-');
            this._set('annualDisplay', aH.length ? this._fmtSol(aH[aH.length - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var d = this._complete(this._flat(state, p), p);
            if (d.recup2 === 'aplazar' && p >= 2) { return this._t('hint_book'); }
            if (p === 1 && (d.triaje1 === 'valor' || d.triaje1 === 'llegada')) { return this._t('hint_triage'); }
            if (p === 1 && d.despliegue1 !== 'competencia') { return this._t('hint_deploy'); }
            if (p === 2 && (d.empod2 === 'cero' || d.empod2 === 'libre')) { return this._t('hint_empod'); }
            if (p === 3 && d.aprendiz3 !== 'justa') { return this._t('hint_diego'); }
            if (p === 3 && (d.registro3 === 'memoria' || d.registro3 === 'libro')) { return this._t('hint_log'); }
            if (p === 4 && d.mejora4 !== 'llaves') { return this._t('hint_fix'); }
            return null;
        }

