        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var m = Math.max(1, n);
            var d = this._complete(this._flat(state, m), m);
            var o = this._outcome(d);
            var composite = this._composite(state);
            var insights = [];
            insights.push(this._t({ llegada: 'fb_tri_llegada', valor: 'fb_tri_valor', seguridad: 'fb_tri_seguridad', rapidas: 'fb_tri_rapidas' }[d.triaje1]));
            insights.push(this._t({ yo: 'fb_dep_yo', disponible: 'fb_dep_disponible', competencia: 'fb_dep_competencia', regional: 'fb_dep_regional' }[d.despliegue1]));
            if (o.evac) { insights.push(this._t('fb_evac')); }
            if (m >= 2) {
                insights.push(this._t({ cero: 'fb_emp_cero', plano: 'fb_emp_plano', escalonada: 'fb_emp_escalonada', libre: 'fb_emp_libre' }[d.empod2]));
                insights.push(this._t({ disculpa: 'fb_rec_disculpa', proporcional: 'fb_rec_proporcional', noche: 'fb_rec_noche', aplazar: 'fb_rec_aplazar' }[d.recup2]));
            }
            if (m >= 3) {
                insights.push(this._t({ memoria: 'fb_log_memoria', libro: 'fb_log_libro', digital: 'fb_log_digital', causa: 'fb_log_causa' }[d.registro3]));
                insights.push(this._t({ amonestacion: 'fb_ap_amonestacion', nada: 'fb_ap_nada', justa: 'fb_ap_justa', retirar: 'fb_ap_retirar' }[d.aprendiz3]));
            }
            if (m >= 4) {
                insights.push(this._t({ curso: 'fb_fix_curso', llaves: 'fb_fix_llaves', alarmas: 'fb_fix_alarmas', estado: 'fb_fix_estado' }[d.mejora4]));
            }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                night: Math.round(o.nightCost),
                rec: Math.round(o.recovered * 100),
                key: Math.round(o.key),
                compl: o.complaints,
                annual: Math.round(o.annual),
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
